/**
 * Phosphor icons (MIT), for the controls: regular, bold for the few that act alone, filled for a
 * state that is on. Each is the path data of the icon's SVG. What files and places look like is [MntFlat].
 */
object MntIcons {
    // Phosphor draws on 256 with a wide margin; the viewport is cut to 224 so a glyph fills its box as the old ones did.
    private fun icon(name: String, vararg paths: Pair<String, Float>) =
        ImageVector.Builder(name, 24.dp, 24.dp, 224f, 224f).apply {
            addGroup(translationX = -16f, translationY = -16f)
            paths.forEach { (data, alpha) -> addPath(PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black), fillAlpha = alpha) }
            clearGroup()
        }.build()

